// Verus program: count transitions between regions A (x>y) and B (y>x)
// along a path of 'U'/'R' moves starting from (0,0).

use vstd::prelude::*;

verus! {

fn solve(n: i8, s: Vec<char>) -> (res: i8)
    requires
        n >= 0,
        s.len() == n as usize,
        // Every move is either 'U' or 'R'
        forall|i: int| 0 <= i < s.len() ==> (s[i] == 'U' || s[i] == 'R'),
        // Prevent i8 overflow for x,y, and for the transition count.
        n <= i8::MAX,
    ensures
        0 <= res <= n,
        n == 0 ==> res == 0,
{
    let mut x: i8 = 0;
    let mut y: i8 = 0;

    // last_region: 0 = none yet, 1 = Region A (x>y), 2 = Region B (y>x)
    let mut last_region: i8 = 0;
    let mut transitions: i8 = 0;

    let mut i: usize = 0;

    while i < s.len()
        invariant
            i <= s.len(),
            // x and y are the number of R and U moves processed so far (respectively),
            // hence non-negative and bounded by i and by n.
            0 <= x <= i as i8,
            0 <= y <= i as i8,
            x + y == i as i8,
            i as i8 <= n,
            // bookkeeping vars are in-range
            0 <= transitions <= i as i8,
            last_region == 0 || last_region == 1 || last_region == 2,
        decreases s.len() - i
    {
        let c = s[i];

        // Apply move
        if c == 'U' {
            // y <= i, and i < n <= i8::MAX, so y+1 doesn't overflow
            y = y + 1;
        } else {
            // must be 'R' by requires
            x = x + 1;
        }

        // Determine current region after the move
        // region: 0 = border, 1 = A, 2 = B
        let mut region: i8 = 0;
        if x > y {
            region = 1;
        } else if y > x {
            region = 2;
        } else {
            region = 0;
        }

        // Count transition only when entering a strict region and it differs from
        // the last strict region visited (ignoring time on the border).
        if region != 0 {
            if last_region != 0 && region != last_region {
                transitions = transitions + 1;
            }
            last_region = region;
        }

        i = i + 1;
    }

    res = transitions;

    // Help the verifier with the n=0 edge postcondition
    if n == 0 {
        assert(s.len() == 0);
        assert(res == 0);
    }
}

} // verus!